/bin/zsh -lc "cd /Users/chenzhenbo/Work/TriviumCode && node --input-type=module -e \"
const {validateTopic} = await import('./dist/test/src/trivium/naming.js');
const {buildDenySettings, denyRuleShapeOf, readonlyToolsFromProbe} = await import('./dist/test/src/trivium/adapters/claude.js');
const {READONLY_INVARIANTS} = await import('./dist/test/src/trivium/probes/claude.js');
for (const t of ['M9(收口)','a,b','fix*','M9[3]','M9 收口','ok-topic']) console.log(JSON.stringify(t), JSON.stringify(validateTopic(t)));
const tools = readonlyToolsFromProbe(READONLY_INVARIANTS);
const shape = denyRuleShapeOf('Read(./x/**)');
const paths = ['.reviews/M9(收口)/code/2026-01-01-M9(收口)-gemini.md', '.reviews/M9(收口)/plan/2026-01-01-M9(收口)-glm.md', '.env.example', '.trivium'];
const b = buildDenySettings(paths, tools, shape);
console.log('skipped:', JSON.stringify(b.skipped), 'rules:', b.ruleCount, 'bytes:', b.bytes);
const c = buildDenySettings(['.reviews/fix*/code/a.md'], tools, shape);
console.log('star rule sample:', JSON.parse(c.json).permissions.deny.slice(0,2));
const d = buildDenySettings(['.reviews/M9[3]/code/a.md'], tools, shape);
console.log('bracket rule sample:', JSON.parse(d.json).permissions.deny.slice(0,2), 'skipped:', JSON.stringify(d.skipped));
\" 2>&1 | tail -12"

